import math
    import random
    import time

    LANGUAGE_WRAPPER = 'How many real numbers $x$ satisfy the equation $\\log_{{b}}(x^2+1) = \\cos({{c}}\\pi x)$?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# k determines the base of the logarithm b = k^2+1
# This ensures that the domain of interest for x has an integer boundary.
k = rng.randint(2, 10)
c = rng.randint(2, 10)
b = k**2 + 1

# Retry if parameters are too simple
while k * c < 5:
    k = rng.randint(2, 10)
    c = rng.randint(2, 10)

b = k**2 + 1

return {
    'b': b,
    'c': c,
    # k is not part of the problem statement, but needed for verification
    'k': k
}

    def verifier(assign):
b = assign['b']
c = assign['c']
k = assign.get('k')

# Validate that k is provided and consistent with b
if k is None:
    return False, None # k is required for the solution
if b != k**2 + 1:
    return False, None # b must be of the form k^2+1

# Validate parameter ranges to ensure difficulty
if k < 2 or c < 2:
    return False, None # Trivial cases
if k * c < 5:
    return False, None # Avoids very small answer counts

# The number of solutions is 2*c*k
answer = 2 * c * k
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
